actions.script:
// an empty Map for each of the metric, class total and ratio names above
salesMap = {}; grossProfitMap = {}; ebtMap = {}; ibieMap = {}; ebitMap = {}
costOfSalesMap = {}; cogsMap = {}; totalAssetsMap = {}; netFixedAssetsMap = {}; currentAssetsMap = {}
currentLiabilitiesMap = {}; inventoryMap = {}; totalLiabilitiesMap = {}; longTermDebtMap = {}; equityMap = {}
accountsReceivableMap = {}; depreciationMap = {}; amortizationMap = {}; interestExpenseMap = {}
currentLiquidityMap = {}; quickLiquidityMap = {}; netCapitalToAssetsMap = {}; inventoryTurnoverMap = {}
collectionPeriodMap = {}; fixedAssetTurnoverMap = {}; totalAssetsTurnoverMap = {}; debtRatioMap = {}
debtToEquityMap = {}; timesInterestEarnedMap = {}; cashCoverageMap = {}; fixedChargeCoverageMap = {}
equityMultiplierMap = {}; grossProfitMarginMap = {}; netProfitMarginMap = {}; returnOnAssetsMap = {}
returnOnEquityMap = {}

const zero = toDecimal(0)
const dec = (value) => toDecimal(value ?? 0)
const negated = (value) => value.multiply(-1)
// a class total for a time period, zero when there is none
const classVal = (classId, totalName, timePeriodId) => dec(classInfoById[classId]?.[totalName]?.[timePeriodId])
const ratio = (numerator, denominator) => denominator.isZero() ? zero : numerator.divide(denominator)
const addDec = (key, value, map) => { if (value != null) map[key] = map[key] == null ? toDecimal(value) : toDecimal(map[key]).add(value) }

// Ratios from the values for one time period, or for ALL periods
const putRatios = (key, v) => {
    // Liquidity: Ability to meet short-term obligations
    // Current Liquidity = currentAssets / currentLiabilities
    currentLiquidityMap[key] = ratio(v.currentAssets, v.currentLiabilities)
    // Quick Liquidity = (currentAssets - inventory) / currentLiabilities
    quickLiquidityMap[key] = ratio(v.currentAssets.subtract(v.inventory), v.currentLiabilities)
    // Net Working Capital to Total Assets = (currentAssets - inventory) / totalAssets
    netCapitalToAssetsMap[key] = ratio(v.currentAssets.subtract(v.inventory), v.totalAssets)

    // Activity: Efficiency in generating sales with assets
    // Inventory Turnover = cogs / inventory (NOTE: should be "average" inventory...)
    inventoryTurnoverMap[key] = ratio(v.cogs, v.inventory)
    // TODO: Collection Period = accountsReceivable / (credit sales per day??? - maybe REVENUE/(days in period))
    // Fixed Asset Turnover = sales / netFixedAssets
    fixedAssetTurnoverMap[key] = ratio(v.sales, v.netFixedAssets)
    // Total Assets Turnover = sales / totalAssets
    totalAssetsTurnoverMap[key] = ratio(v.sales, v.totalAssets)

    // Leverage: Degree of indebtedness and ability to meet long term obligations
    // Debt Ratio = totalLiabilities / totalAssets
    debtRatioMap[key] = ratio(v.totalLiabilities, v.totalAssets)
    // Debt to Equity = longTermDebt / equity
    debtToEquityMap[key] = ratio(v.longTermDebt, v.equity)
    // Times Interest Earned = ebit / interestExpense
    timesInterestEarnedMap[key] = ratio(v.ebit, v.interestExpense)
    // Cash Coverage = (ebit + depreciation + amortization) / interestExpense
    cashCoverageMap[key] = ratio(v.ebit.add(v.depreciation).add(v.amortization), v.interestExpense)
    // TODO: Fixed Charge Coverage = (ebit + [lease payments]) / (interestExpense + [lease payments])
    // Equity Multiplier = totalAssets / equity
    equityMultiplierMap[key] = ratio(v.totalAssets, v.equity)

    // Profitability: Returns on assets and equity
    // Gross Profit Margin = grossProfit / sales
    grossProfitMarginMap[key] = ratio(v.grossProfit, v.sales)
    // Net Profit Margin = netIncome / sales
    netProfitMarginMap[key] = ratio(v.netIncome, v.sales)
    // Return on Assets = netIncome / totalAssets
    returnOnAssetsMap[key] = ratio(v.netIncome, v.totalAssets)
    // Return on Equity = netIncome / equity
    returnOnEquityMap[key] = ratio(v.netIncome, v.equity)
    // NOTE FUTURE need values split by share, count of shares, etc: Price/Earnings, Earnings per Share, Market-to-Book
}

// the class totals and metrics also get a total across all periods under ALL
const totalMaps = [costOfSalesMap, cogsMap, totalAssetsMap, netFixedAssetsMap, currentAssetsMap, currentLiabilitiesMap,
        inventoryMap, totalLiabilitiesMap, longTermDebtMap, equityMap, accountsReceivableMap, depreciationMap,
        amortizationMap, interestExpenseMap, salesMap, grossProfitMap, ebtMap, ibieMap, ebitMap]

for (const timePeriodId of timePeriodIdList) {

    // ========== GL Class Totals ==========

    const costOfSales = negated(classVal('COST_OF_SALES', 'totalPostedByTimePeriod', timePeriodId))
    costOfSalesMap[timePeriodId] = costOfSales
    const cogs = negated(classVal('COST_GOODS_SOLD', 'totalPostedByTimePeriod', timePeriodId))
    cogsMap[timePeriodId] = cogs

    // Total Assets = ASSET
    const totalAssets = classVal('ASSET', 'totalBalanceByTimePeriod', timePeriodId)
    totalAssetsMap[timePeriodId] = totalAssets
    const netFixedAssets = classVal('LONG_TERM_ASSET', 'totalBalanceByTimePeriod', timePeriodId)
    netFixedAssetsMap[timePeriodId] = netFixedAssets
    const currentAssets = classVal('CURRENT_ASSET', 'totalBalanceByTimePeriod', timePeriodId)
    currentAssetsMap[timePeriodId] = currentAssets
    const currentLiabilities = negated(classVal('CURRENT_LIABILITY', 'totalBalanceByTimePeriod', timePeriodId))
    currentLiabilitiesMap[timePeriodId] = currentLiabilities
    const inventory = classVal('INVENTORY_ASSET', 'totalBalanceByTimePeriod', timePeriodId)
    inventoryMap[timePeriodId] = inventory

    const totalLiabilities = negated(classVal('LIABILITY', 'totalBalanceByTimePeriod', timePeriodId))
    totalLiabilitiesMap[timePeriodId] = totalLiabilities
    const longTermDebt = negated(classVal('LONG_TERM_LIABILITY', 'totalBalanceByTimePeriod', timePeriodId))
    longTermDebtMap[timePeriodId] = longTermDebt
    const equity = classVal('EQUITY', 'totalBalanceByTimePeriod', timePeriodId)
    equityMap[timePeriodId] = equity

    const accountsReceivable = negated(classVal('ACCOUNTS_RECEIVABLE', 'totalBalanceByTimePeriod', timePeriodId))
    accountsReceivableMap[timePeriodId] = accountsReceivable
    const depreciation = negated(classVal('DEPRECIATION', 'totalPostedByTimePeriod', timePeriodId))
    depreciationMap[timePeriodId] = depreciation
    const amortization = negated(classVal('AMORTIZATION', 'totalPostedByTimePeriod', timePeriodId))
    amortizationMap[timePeriodId] = amortization
    const interestExpense = negated(classVal('INTEREST_EXPENSE', 'totalPostedByTimePeriod', timePeriodId))
    interestExpenseMap[timePeriodId] = interestExpense

    // ========== Metrics ==========

    // Sales = REVENUE
    const sales = classVal('REVENUE', 'totalPostedByTimePeriod', timePeriodId)
    salesMap[timePeriodId] = sales
    // Gross Profit = sales - costOfSales
    const grossProfit = sales.subtract(costOfSales)
    grossProfitMap[timePeriodId] = grossProfit

    // Net Income = (standard Net Income from run#IncomeStatement service)
    const netIncome = dec(netIncomeMap[timePeriodId])
    // EBT = Net Income - INCOME_TAX_EXPENSE (negated, so adds back in)
    const ebt = netIncome.subtract(classVal('INCOME_TAX_EXPENSE', 'totalPostedByTimePeriod', timePeriodId))
    ebtMap[timePeriodId] = ebt
    // IBIE = EBT - INTEREST_EXPENSE (negated, so adds back in)
    const ibie = ebt.subtract(classVal('INTEREST_EXPENSE', 'totalPostedByTimePeriod', timePeriodId))
    ibieMap[timePeriodId] = ibie
    // EBIT = IBIE - INTEREST_INCOME
    const ebit = ibie.subtract(classVal('INTEREST_INCOME', 'totalPostedByTimePeriod', timePeriodId))
    ebitMap[timePeriodId] = ebit
    // EBIT + interest income = IBIE; IBIE - interest expense = EBT; EBT - income taxes = Net Income
    // EBIT = Net Income + income taxes + interest expense - interest income

    // ========== Add Class Totals and Metrics to values for ALL periods ==========
    for (const totalMap of totalMaps) addDec('ALL', totalMap[timePeriodId], totalMap)

    // ========== Ratios ==========
    putRatios(timePeriodId, {currentAssets, currentLiabilities, inventory, totalAssets, netFixedAssets, totalLiabilities,
            longTermDebt, equity, cogs, sales, grossProfit, netIncome, ebit, interestExpense, depreciation, amortization})
}

// Calculate ratios for ALL periods
putRatios('ALL', {currentAssets: dec(currentAssetsMap.ALL), currentLiabilities: dec(currentLiabilitiesMap.ALL),
        inventory: dec(inventoryMap.ALL), totalAssets: dec(totalAssetsMap.ALL), netFixedAssets: dec(netFixedAssetsMap.ALL),
        totalLiabilities: dec(totalLiabilitiesMap.ALL), longTermDebt: dec(longTermDebtMap.ALL), equity: dec(equityMap.ALL),
        cogs: dec(cogsMap.ALL), sales: dec(salesMap.ALL), grossProfit: dec(grossProfitMap.ALL), netIncome: dec(netIncomeMap.ALL),
        ebit: dec(ebitMap.ALL), interestExpense: dec(interestExpenseMap.ALL), depreciation: dec(depreciationMap.ALL),
        amortization: dec(amortizationMap.ALL)})

iterate.script:
const addDec = (key, value, map) => { if (value != null) map[key] = map[key] == null ? toDecimal(value) : toDecimal(map[key]).add(value) }
for (const [timePeriodId, value] of Object.entries(classInfo.totalPostedByTimePeriod ?? {})) addDec(timePeriodId, value, totalPosted)
for (const [timePeriodId, value] of Object.entries(classInfo.totalPostedNoClosingByTimePeriod ?? {})) addDec(timePeriodId, value, totalPostedNoClosing)
for (const [timePeriodId, value] of Object.entries(classInfo.totalBalanceByTimePeriod ?? {})) addDec(timePeriodId, value, totalBalance)

actions.script:
const dec = (value) => toDecimal(value ?? 0)
const addDec = (key, value, map) => { if (value != null) map[key] = map[key] == null ? toDecimal(value) : toDecimal(map[key]).add(value) }
for (const glAccountDetail of glAccountDetailList) {
    const isDebit = (glAccountDetail.isDebit === 'Y')
    let balance = dec(glAccountDetail.endingBalance)
    let posted = balance.subtract(dec(glAccountDetail.beginningBalance))
    let postedNoClosing = isDebit ?
            dec(glAccountDetail.postedDebitsNoClosing).subtract(dec(glAccountDetail.postedCreditsNoClosing)) :
            dec(glAccountDetail.postedCreditsNoClosing).subtract(dec(glAccountDetail.postedDebitsNoClosing))
    if (negate) { balance = balance.multiply(-1); posted = posted.multiply(-1); postedNoClosing = postedNoClosing.multiply(-1) }

    addDec(glAccountDetail.timePeriodId, balance, balanceByTimePeriod)
    addDec(glAccountDetail.timePeriodId, posted, postedByTimePeriod)
    addDec(glAccountDetail.timePeriodId, postedNoClosing, postedNoClosingByTimePeriod)
    addDec('ALL', balance, balanceByTimePeriod)
    addDec('ALL', posted, postedByTimePeriod)
    addDec('ALL', postedNoClosing, postedNoClosingByTimePeriod)

    let glAccountInfo = glAccountInfoMap[glAccountDetail.accountCode]
    if (glAccountInfo == null) {
        glAccountInfo = {accountCode:glAccountDetail.accountCode, accountName:glAccountDetail.accountName,
                glAccountId:glAccountDetail.glAccountId, balanceByTimePeriod:{}, postedByTimePeriod:{},
                postedNoClosingByTimePeriod:{}}
        glAccountInfoMap[glAccountDetail.accountCode] = glAccountInfo
    }
    glAccountInfo.balanceByTimePeriod[glAccountDetail.timePeriodId] = balance
    glAccountInfo.postedByTimePeriod[glAccountDetail.timePeriodId] = posted
    glAccountInfo.postedNoClosingByTimePeriod[glAccountDetail.timePeriodId] = postedNoClosing
    addDec('ALL', balance, glAccountInfo.balanceByTimePeriod)
    addDec('ALL', posted, glAccountInfo.postedByTimePeriod)
    addDec('ALL', postedNoClosing, glAccountInfo.postedNoClosingByTimePeriod)
}

iterate.script:
// format the account code with the mask: '#' takes the next character of the code, a code that runs out is padded
// with '0', and any other mask character is a literal, like javax.swing.text.MaskFormatter
accountCode = glAccount.accountCode
if (glAccountCodeMask) {
    const codeText = accountCode == null ? '' : String(accountCode)
    let codeIndex = 0, maskedCode = ''
    for (const maskChar of glAccountCodeMask) {
        if ('#ULA?*H'.includes(maskChar)) { maskedCode += codeIndex < codeText.length ? codeText[codeIndex] : '0'; codeIndex++ }
        else maskedCode += maskChar
    }
    accountCode = maskedCode
}

entryInfoList.push(totalsRow)
entryInfoList.push({transactionDate:thruTimestamp, description:glAccount.accountName, accountCode:accountCode, balance:balance})
if (glAccountOrgTimePeriod_has_next) entryInfoList.push({})

for (const id of childOut.enumIdSet) {
    if (!dataset.classSet.includes(id)) dataset.classSet.push(id)
    if (!allClasses.includes(id)) allClasses.push(id)
}

for (const id of childOut.enumIdSet) {
    if (!dataset.classSet.includes(id)) dataset.classSet.push(id)
    if (!allClasses.includes(id)) allClasses.push(id)
}
